require_once __DIR__ . '/../includes/auth.php'; require_role(['admin']); require __DIR__ . '/../config/database.php'; $pageTitle='Subjects & Classes';$rows=$pdo->query('SELECT s.subject_code,s.subject_name,u.full_name AS teacher FROM subjects s LEFT JOIN users u ON u.id=s.teacher_id ORDER BY s.subject_name')->fetchAll();require __DIR__ . '/../includes/header.php'; ?>
<section class="panel"><div class="panel-head"><h3>Subject records</h3></div><?php if(!$rows): ?><p class="empty">No subjects have been added.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Code</th><th>Subject</th><th>Teacher</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['subject_code']) ?></td><td><?= e($r['subject_name']) ?></td><td><?= e($r['teacher'] ?: 'Unassigned') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="muted section-gap">Subject/class creation and enrollment tools are planned next.</p></section>
